import { useState, useEffect } from 'react';
import { User, Order, OrderStatus, PaymentMethod } from '../types';
import { supabase } from './supabase';

const AUTH_KEY = 'studio_auth_v2';
const ADMIN_EMAIL = "carminephotography0@gmail.com";

// Interfaccia per mappare esattamente le colonne della tabella Supabase
interface SupabaseOrder {
  id: string;
  customer_email: string;
  photo_urls: string[];
  status: string;
  created_at: string;
}

export const useStore = () => {
  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem(AUTH_KEY);
    return stored ? JSON.parse(stored) : null;
  });

  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (user) {
      fetchOrders();
    }
  }, [user]);

  const fetchOrders = async () => {
    if (!user) return;
    setLoading(true);

    try {
      console.log(`[STORE] Recupero ordini per: ${user.email} (Ruolo: ${user.role})`);

      // Iniziamo la query base
      let query = supabase.from('orders').select('*');

      // La RLS di Supabase filtra già i dati, ma applichiamo il filtro esplicito 
      // per chiarezza e per evitare overhead se l'utente non è admin.
      if (user.email !== ADMIN_EMAIL) {
        query = query.eq('customer_email', user.email);
      }

      // Ordinamento per data decrescente (DESC) come richiesto
      const { data, error } = await query.order('created_at', { ascending: false });

      if (error) {
        console.error("[STORE] Errore fetch ordini Supabase:", error.message);
        return;
      }

      if (data) {
        const mappedOrders: Order[] = (data as SupabaseOrder[]).map((item) => ({
          id: item.id,
          userId: '', 
          userName: item.customer_email.split('@')[0],
          userEmail: item.customer_email,
          packageId: 'standard_100', 
          packageName: 'Pacchetto 100 Foto',
          photos: (item.photo_urls || []).map((url: string, index: number) => ({
            id: `photo-${index}`,
            name: `Foto ${index + 1}`,
            url: url,
            size: 0
          })),
          status: (item.status as OrderStatus) || OrderStatus.PENDING_PAYMENT,
          paymentMethod: PaymentMethod.ONLINE_SUMUP,
          createdAt: item.created_at,
          total: 20 
        }));
        setOrders(mappedOrders);
        console.log(`[STORE] Caricati ${mappedOrders.length} ordini.`);
      }
    } catch (err) {
      console.error("[STORE] Eccezione nel caricamento ordini:", err);
    } finally {
      setLoading(false);
    }
  };

  const login = async (email: string, pass: string): Promise<User> => {
    const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
      email,
      password: pass,
    });

    if (authError) {
      console.error("[STORE] Errore Autenticazione Supabase:", authError.message);
      throw authError;
    }

    const role = email.toLowerCase() === ADMIN_EMAIL.toLowerCase() ? 'admin' : 'client';
    const loggedUser: User = {
      id: authData.user.id,
      name: authData.user.email?.split('@')[0] || email.split('@')[0],
      email: email.toLowerCase(),
      role: role as 'admin' | 'client',
      mustChangePassword: false
    };

    setUser(loggedUser);
    localStorage.setItem(AUTH_KEY, JSON.stringify(loggedUser));
    return loggedUser;
  };

  const signUp = async (email: string, pass: string): Promise<User> => {
    // Registrazione: Supabase è configurato per NON richiedere conferma email
    const { data: authData, error: authError } = await supabase.auth.signUp({
      email,
      password: pass,
    });

    if (authError) {
      console.error("[STORE] Errore Registrazione Supabase:", authError.message);
      throw authError;
    }

    const newUser: User = {
      id: authData.user?.id || Math.random().toString(36).substr(2, 9),
      name: email.split('@')[0],
      email: email.toLowerCase(),
      role: 'client',
      mustChangePassword: false
    };

    setUser(newUser);
    localStorage.setItem(AUTH_KEY, JSON.stringify(newUser));
    return newUser;
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    localStorage.removeItem(AUTH_KEY);
    setOrders([]);
  };

  const addOrder = async (order: Order) => {
    // Prepariamo i dati ESATTAMENTE come richiesto dalla tabella
    const dbOrder = {
      customer_email: order.userEmail.toLowerCase(),
      photo_urls: order.photos.map(p => p.url),
      status: 'pending',
      created_at: new Date().toISOString()
    };

    console.log("[STORE] Invio dati a Supabase (Tabella orders):", dbOrder);

    const { data, error } = await supabase.from('orders').insert([dbOrder]).select();

    if (error) {
      console.error("[STORE] Errore salvataggio Supabase (RLS o Schema):", error);
      throw error;
    }

    console.log("[STORE] Risposta successo Supabase:", data);

    // Aggiornamento immediato lista locale
    await fetchOrders();

    return data ? data[0] : null;
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus) => {
    console.log(`[STORE] Aggiornamento status ordine ${orderId} a ${status}`);
    const { error } = await supabase
      .from('orders')
      .update({ status })
      .eq('id', orderId);

    if (error) {
      console.error("[STORE] Errore update status Supabase:", error.message);
      throw error;
    }

    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status } : o));
  };

  const deleteOrder = async (orderId: string) => {
    console.log(`[STORE] Eliminazione definitiva ordine ${orderId}`);
    const { error } = await supabase
      .from('orders')
      .delete()
      .eq('id', orderId);

    if (error) {
      console.error("[STORE] Errore eliminazione Supabase:", error.message);
      throw error;
    }

    setOrders(prev => prev.filter(o => o.id !== orderId));
  };

  return {
    user,
    orders,
    loading,
    login,
    signUp,
    logout,
    addOrder,
    updateOrderStatus,
    deleteOrder,
    fetchOrders
  };
};

import * as React from 'react';
import { useState, useRef, type FC } from 'react';
import { User, PhotoPackage, PhotoFile, Order, OrderStatus, PaymentMethod } from '../types';
import { PRINT_PACKAGES, SUMUP_PAY_LINK } from '../constants';
import { EmailService } from '../services/email';

interface DashboardProps {
  user: User;
  orders: Order[];
  addOrder: (order: Order) => Promise<any>;
  updateStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  navigate: (page: string) => void;
  onLogout: () => void;
}

const Dashboard: FC<DashboardProps> = ({ user, orders, addOrder, updateStatus, navigate, onLogout }) => {
  const [selectedPackage, setSelectedPackage] = useState<PhotoPackage | null>(PRINT_PACKAGES.length === 1 ? PRINT_PACKAGES[0] : null);
  const [localFiles, setLocalFiles] = useState<File[]>([]);
  const [uploadedPhotosPreview, setUploadedPhotosPreview] = useState<PhotoFile[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isFinalizing, setIsFinalizing] = useState(false);
  const [showCheckout, setShowCheckout] = useState(false);
  const [currentOrderId, setCurrentOrderId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const uploadToCloudinary = async (file: File): Promise<string> => {
    console.log(`[UPLOAD] Avvio caricamento Cloudinary per: ${file.name} (${(file.size / 1024).toFixed(2)} KB)`);

    const formData = new FormData();
    formData.append("file", file);
    formData.append("upload_preset", "fotocs");

    const response = await fetch("https://api.cloudinary.com/v1_1/divyx0t5b/image/upload", {
      method: "POST",
      body: formData,
    });

    const data = await response.json();

    if (!response.ok) {
      console.error("[UPLOAD] Fallimento Cloudinary:", data);
      throw new Error(data.error?.message || "Errore durante l'upload dell'immagine.");
    }

    console.log(`[UPLOAD] Successo Cloudinary per ${file.name}:`, data.secure_url);
    return data.secure_url;
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !selectedPackage) return;

    const newFiles = Array.from(files);
    console.log("[FILES] File selezionati dall'utente:", newFiles.map(f => f.name));

    const totalAllowed = selectedPackage.count;
    const currentCount = localFiles.length;
    const remaining = Math.max(0, totalAllowed - currentCount);

    const filesToAdd = newFiles.slice(0, remaining);

    if (newFiles.length > remaining && remaining > 0) {
      alert(`Puoi aggiungere solo altre ${remaining} foto per questo pacchetto.`);
    } else if (remaining === 0) {
      alert(`Hai già raggiunto il limite di ${totalAllowed} foto.`);
      return;
    }

    setLocalFiles(prev => [...prev, ...filesToAdd]);

    const newPreviews: PhotoFile[] = filesToAdd.map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      name: file.name,
      size: file.size,
      url: URL.createObjectURL(file)
    }));

    setUploadedPhotosPreview(prev => [...prev, ...newPreviews]);
  };

  const resetForm = () => {
    console.log("[UI] Reset del modulo di upload.");
    setLocalFiles([]);
    setUploadedPhotosPreview([]);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleSubmit = async (e: React.MouseEvent | React.FormEvent) => {
    if (e) e.preventDefault();

    if (!selectedPackage || localFiles.length === 0) {
      alert("Seleziona almeno una foto prima di procedere.");
      return;
    }

    console.log("[FLOW] Inizio procedura d'invio ordine...");
    setIsUploading(true);

    try {
      const uploadedUrls: PhotoFile[] = [];

      // Caricamento sequenziale per stabilità su reti mobili
      for (const file of localFiles) {
        const secureUrl = await uploadToCloudinary(file);
        uploadedUrls.push({
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          size: file.size,
          url: secureUrl
        });
      }

      console.log("[FLOW] Tutti i file sono su Cloudinary. Salvataggio su Supabase...");

      const newOrderData: Order = {
        id: `TEMP-${Date.now()}`, 
        userId: user.id,
        userName: user.name,
        userEmail: user.email,
        packageId: selectedPackage.id,
        packageName: selectedPackage.name,
        photos: uploadedUrls,
        status: OrderStatus.PENDING_PAYMENT, 
        paymentMethod: PaymentMethod.ONLINE_SUMUP,
        createdAt: new Date().toISOString(),
        total: selectedPackage.price
      };

      // Salvataggio nel database tramite store (gestisce RLS e campi corretti)
      const savedOrder = await addOrder(newOrderData);

      const finalId = savedOrder?.id || newOrderData.id;
      setCurrentOrderId(finalId);

      // Reset dei file dopo il salvataggio avvenuto con successo
      resetForm();

      // Passaggio alla fase di checkout
      setShowCheckout(true);

      alert("Foto caricate con successo! Procedi ora al pagamento.");

      // Notifica email silenziosa
      EmailService.sendOrderConfirmation({...newOrderData, id: finalId}).catch(err => console.error("Email service error:", err));

    } catch (error: any) {
      console.error("[FLOW] ERRORE CRITICO:", error);
      alert("Si è verificato un errore: " + (error.message || "Riprova tra qualche istante."));
    } finally {
      setIsUploading(false);
    }
  };

  const finalizePayment = async () => {
    if (!currentOrderId) return;

    console.log(`[PAYMENT] Apertura SumUp per l'ordine: ${currentOrderId}`);
    const paymentWindow = window.open(SUMUP_PAY_LINK, '_blank');
    setIsFinalizing(true);

    try {
      // Aggiorniamo lo status nel database
      await updateStatus(currentOrderId, OrderStatus.PAID);

      setShowCheckout(false);
      setCurrentOrderId(null);
      alert("Pagamento registrato! Riceverai un'email quando le foto saranno pronte.");
    } catch (error) {
      console.error("[PAYMENT] Errore aggiornamento stato dopo pagamento:", error);
      alert("Il pagamento è stato avviato, ma c'è stato un problema nell'aggiornare lo stato. Contattaci se necessario.");
    } finally {
      setIsFinalizing(false);
    }
  };

  const currentStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING_PAYMENT: return 'bg-orange-100 text-orange-700';
      case OrderStatus.PAID: return 'bg-green-100 text-green-700';
      case OrderStatus.PROCESSING: return 'bg-blue-100 text-blue-700';
      case OrderStatus.PRINTED: return 'bg-purple-100 text-purple-700';
      case OrderStatus.COLLECTED: return 'bg-emerald-100 text-emerald-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  const handleRemovePhoto = (id: string, index: number) => {
    setUploadedPhotosPreview(prev => prev.filter(p => p.id !== id));
    setLocalFiles(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="py-12 px-4 md:px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-12">
        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white p-6 md:p-12 rounded-[40px] shadow-sm border border-gray-100">
            <h2 className="text-2xl md:text-3xl font-serif mb-8 text-black italic">Il tuo Ordine</h2>
            {!selectedPackage ? (
              <div className="space-y-6">
                <p className="text-gray-500 mb-6 font-bold uppercase tracking-widest text-[10px]">1. Seleziona il pacchetto</p>
                <div className="grid grid-cols-1 gap-6">
                  {PRINT_PACKAGES.map(pkg => (
                    <button 
                      key={pkg.id}
                      onClick={() => setSelectedPackage(pkg)}
                      className="p-8 border-2 border-gray-50 rounded-3xl text-left hover:border-black hover:shadow-xl transition-all bg-gray-50/50"
                    >
                      <h4 className="font-bold text-lg">{pkg.name}</h4>
                      <p className="text-sm text-gray-400 mt-1">{pkg.count} foto professionali</p>
                      <p className="text-2xl font-serif font-bold mt-4">€{pkg.price}</p>
                    </button>
                  ))}
                </div>
              </div>
            ) : !showCheckout ? (
              <div className="space-y-8">
                <div className="flex items-center justify-between p-6 bg-gray-50 rounded-3xl border border-gray-100">
                  <div className="flex-grow">
                    <h4 className="font-bold text-lg md:text-xl uppercase tracking-tighter italic">{selectedPackage.name}</h4>
                    <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">
                      {uploadedPhotosPreview.length} / {selectedPackage.count} foto caricate
                    </p>
                  </div>
                </div>

                <div 
                  onClick={() => !isUploading && fileInputRef.current?.click()}
                  className={`border-2 border-dashed rounded-[40px] p-8 md:p-16 text-center cursor-pointer transition-all ${isUploading ? 'bg-gray-100 opacity-70 pointer-events-none' : 'hover:bg-gray-50/80 hover:border-black bg-gray-50/30 border-gray-200'}`}
                >
                  <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileSelect} />
                  {isUploading ? (
                    <div className="flex flex-col items-center">
                        <div className="w-12 h-12 border-4 border-black border-t-transparent rounded-full animate-spin mb-4"></div>
                        <p className="font-bold uppercase tracking-[0.2em] text-[10px]">Caricamento in corso... attendere</p>
                    </div>
                  ) : (
                    <>
                        <div className="w-12 h-12 md:w-16 md:h-16 bg-white rounded-2xl shadow-sm flex items-center justify-center mx-auto mb-6 text-black border border-gray-100">
                          <i className="fas fa-upload text-xl md:text-2xl"></i>
                        </div>
                        <h4 className="font-bold text-base md:text-lg mb-2 text-black uppercase tracking-widest">Scegli le tue foto</h4>
                        <p className="text-xs text-gray-400 font-medium italic">Seleziona i file dal tuo dispositivo</p>
                    </>
                  )}
                </div>

                {uploadedPhotosPreview.length > 0 && (
                  <div className="grid grid-cols-3 sm:grid-cols-4 lg:grid-cols-5 gap-3 md:gap-4">
                    {uploadedPhotosPreview.map((photo, index) => (
                      <div key={photo.id} className="relative aspect-square rounded-xl overflow-hidden border border-gray-100 shadow-sm">
                        <img src={photo.url} alt={photo.name} className="w-full h-full object-cover" />
                        {!isUploading && (
                          <button onClick={(e) => { e.stopPropagation(); handleRemovePhoto(photo.id, index); }} className="absolute top-1 right-1 bg-black/80 text-white w-6 h-6 rounded-full shadow-md flex items-center justify-center">
                            <i className="fas fa-times text-[8px]"></i>
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                {uploadedPhotosPreview.length > 0 && (
                  <div className="pt-8 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6">
                    <p className="text-xl md:text-2xl font-serif font-bold text-black italic">Prezzo: €{selectedPackage.price}</p>
                    <button 
                      onClick={handleSubmit} 
                      disabled={isUploading}
                      className="w-full sm:w-auto px-12 py-5 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-2xl transition-all uppercase tracking-[0.2em] text-[10px] disabled:opacity-50"
                    >
                      {isUploading ? 'Salvataggio...' : 'Conferma e procedi'}
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-8 py-4">
                <div className="text-center mb-10">
                   <h3 className="text-2xl md:text-3xl font-serif mb-4 italic">Ordine Ricevuto!</h3>
                   <p className="text-gray-500 italic text-sm">Abbiamo salvato correttamente le tue foto.</p>
                </div>

                <div className="max-w-md mx-auto bg-gray-50 p-8 md:p-12 rounded-[50px] border border-gray-100 text-center shadow-lg">
                   <div className="w-20 h-20 bg-black text-white rounded-[28px] flex items-center justify-center mx-auto mb-8 text-3xl shadow-xl">
                      <i className="fas fa-credit-card"></i>
                   </div>
                   <h4 className="font-bold text-lg mb-4 uppercase tracking-widest italic">Pagamento sicuro</h4>
                   <p className="text-[10px] text-gray-400 mb-10 leading-relaxed font-bold uppercase tracking-widest leading-loose">
                      Completa l'operazione con SumUp per avviare la stampa.
                   </p>
                   <button 
                    onClick={finalizePayment}
                    disabled={isFinalizing}
                    className="w-full py-5 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-2xl transition-all uppercase tracking-[0.2em] text-[10px] flex items-center justify-center gap-4 disabled:opacity-50"
                   >
                      {isFinalizing ? 'Attendi...' : 'Paga ora online'}
                      {!isFinalizing && <i className="fas fa-external-link-alt"></i>}
                   </button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-white p-8 md:p-10 rounded-[40px] shadow-sm border border-gray-100">
            <div className="flex items-center space-x-6 mb-8">
              <div className="w-16 h-16 bg-black text-white rounded-[20px] flex items-center justify-center text-2xl font-serif shadow-xl italic">
                {user.name[0].toUpperCase()}
              </div>
              <div>
                <h3 className="font-bold text-xl text-black leading-none italic">{user.name}</h3>
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest mt-2">Profilo Attivo</p>
              </div>
            </div>
            <button onClick={onLogout} className="w-full py-4 border border-gray-100 text-gray-400 hover:text-red-600 rounded-2xl text-[9px] font-bold uppercase tracking-[0.2em] transition-all">
               CHIUDI SESSIONE
            </button>
          </div>

          <div className="bg-white p-8 md:p-10 rounded-[40px] shadow-sm border border-gray-100">
            <h2 className="text-lg font-serif mb-8 text-black border-b border-gray-50 pb-5 italic">I tuoi Ordini</h2>
            {orders.length === 0 ? (
              <p className="text-gray-400 text-[9px] font-bold uppercase tracking-widest text-center py-10 italic">Ancora nessun ordine.</p>
            ) : (
              <div className="space-y-4">
                {orders.map(order => (
                  <div key={order.id} className="p-5 border border-gray-100 rounded-2xl bg-gray-50/50">
                    <div className="flex justify-between items-start mb-3">
                      <span className="text-[8px] font-bold text-gray-300 uppercase tracking-widest">ID: {order.id.slice(0, 8)}</span>
                      <span className={`px-2 py-0.5 rounded-full text-[8px] font-bold uppercase border ${currentStatusColor(order.status)}`}>
                        {order.status}
                      </span>
                    </div>
                    <p className="font-bold text-xs text-gray-900 mb-1 italic">{order.packageName}</p>
                    <p className="text-[8px] text-gray-400 uppercase font-bold tracking-widest">{order.photos.length} Foto &bull; €{order.total}</p>
                    <p className="text-[7px] text-gray-300 mt-2">{new Date(order.createdAt).toLocaleDateString()}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import * as React from 'react';
import { useState, useRef, type FC } from 'react';
import { User, PhotoPackage, PhotoFile, Order, OrderStatus, PaymentMethod } from '../types';
import { PRINT_PACKAGES, SUMUP_PAY_LINK } from '../constants';
import { EmailService } from '../services/email';

interface DashboardProps {
  user: User;
  orders: Order[];
  addOrder: (order: Order) => Promise<any>;
  updateStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  navigate: (page: string) => void;
  onLogout: () => void;
}

const Dashboard: FC<DashboardProps> = ({ user, orders, addOrder, updateStatus, navigate, onLogout }) => {
  const [selectedPackage, setSelectedPackage] = useState<PhotoPackage | null>(PRINT_PACKAGES.length === 1 ? PRINT_PACKAGES[0] : null);
  const [localFiles, setLocalFiles] = useState<File[]>([]);
  const [uploadedPhotosPreview, setUploadedPhotosPreview] = useState<PhotoFile[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isFinalizing, setIsFinalizing] = useState(false);
  const [showCheckout, setShowCheckout] = useState(false);
  const [currentOrderId, setCurrentOrderId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const uploadToCloudinary = async (file: File): Promise<string> => {
    console.log(`[UPLOAD] Avvio caricamento Cloudinary per: ${file.name} (${(file.size / 1024).toFixed(2)} KB)`);

    const formData = new FormData();
    formData.append("file", file);
    formData.append("upload_preset", "fotocs");

    const response = await fetch("https://api.cloudinary.com/v1_1/divyx0t5b/image/upload", {
      method: "POST",
      body: formData,
    });

    const data = await response.json();

    if (!response.ok) {
      console.error("[UPLOAD] Fallimento Cloudinary:", data);
      throw new Error(data.error?.message || "Errore durante l'upload dell'immagine.");
    }

    console.log(`[UPLOAD] Successo Cloudinary per ${file.name}:`, data.secure_url);
    return data.secure_url;
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !selectedPackage) return;

    // Fix: Cast Array.from(files) to File[] to avoid 'unknown' type errors on line 55
    const newFiles = Array.from(files) as File[];
    console.log("[FILES] File selezionati dall'utente:", newFiles.map(f => f.name));

    const totalAllowed = selectedPackage.count;
    const currentCount = localFiles.length;
    const remaining = Math.max(0, totalAllowed - currentCount);

    const filesToAdd = newFiles.slice(0, remaining);

    if (newFiles.length > remaining && remaining > 0) {
      alert(`Puoi aggiungere solo altre ${remaining} foto per questo pacchetto.`);
    } else if (remaining === 0) {
      alert(`Hai già raggiunto il limite di ${totalAllowed} foto.`);
      return;
    }

    setLocalFiles(prev => [...prev, ...filesToAdd]);

    // Fix: Accessing file properties now that filesToAdd is correctly inferred as File[] (fixes lines 74, 75, 76)
    const newPreviews: PhotoFile[] = filesToAdd.map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      name: file.name,
      size: file.size,
      url: URL.createObjectURL(file)
    }));

    setUploadedPhotosPreview(prev => [...prev, ...newPreviews]);
  };

  const resetForm = () => {
    console.log("[UI] Reset del modulo di upload.");
    setLocalFiles([]);
    setUploadedPhotosPreview([]);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleSubmit = async (e: React.MouseEvent | React.FormEvent) => {
    if (e) e.preventDefault();

    if (!selectedPackage || localFiles.length === 0) {
      alert("Seleziona almeno una foto prima di procedere.");
      return;
    }

    console.log("[FLOW] Inizio procedura d'invio ordine...");
    setIsUploading(true);

    try {
      const uploadedUrls: PhotoFile[] = [];

      // Caricamento sequenziale per stabilità su reti mobili
      for (const file of localFiles) {
        const secureUrl = await uploadToCloudinary(file);
        uploadedUrls.push({
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          size: file.size,
          url: secureUrl
        });
      }

      console.log("[FLOW] Tutti i file sono su Cloudinary. Salvataggio su Supabase...");

      const newOrderData: Order = {
        id: `TEMP-${Date.now()}`, 
        userId: user.id,
        userName: user.name,
        userEmail: user.email,
        packageId: selectedPackage.id,
        packageName: selectedPackage.name,
        photos: uploadedUrls,
        status: OrderStatus.PENDING_PAYMENT, 
        paymentMethod: PaymentMethod.ONLINE_SUMUP,
        createdAt: new Date().toISOString(),
        total: selectedPackage.price
      };

      // Salvataggio nel database tramite store (gestisce RLS e campi corretti)
      const savedOrder = await addOrder(newOrderData);

      const finalId = savedOrder?.id || newOrderData.id;
      setCurrentOrderId(finalId);

      // Reset dei file dopo il salvataggio avvenuto con successo
      resetForm();

      // Passaggio alla fase di checkout
      setShowCheckout(true);

      alert("Foto caricate con successo! Procedi ora al pagamento.");

      // Notifica email silenziosa
      EmailService.sendOrderConfirmation({...newOrderData, id: finalId}).catch(err => console.error("Email service error:", err));

    } catch (error: any) {
      console.error("[FLOW] ERRORE CRITICO:", error);
      alert("Si è verificato un errore: " + (error.message || "Riprova tra qualche istante."));
    } finally {
      setIsUploading(false);
    }
  };

  const finalizePayment = async () => {
    if (!currentOrderId) return;

    console.log(`[PAYMENT] Apertura SumUp per l'ordine: ${currentOrderId}`);
    const paymentWindow = window.open(SUMUP_PAY_LINK, '_blank');
    setIsFinalizing(true);

    try {
      // Aggiorniamo lo status nel database
      await updateStatus(currentOrderId, OrderStatus.PAID);

      setShowCheckout(false);
      setCurrentOrderId(null);
      alert("Pagamento registrato! Riceverai un'email quando le foto saranno pronte.");
    } catch (error) {
      console.error("[PAYMENT] Errore aggiornamento stato dopo pagamento:", error);
      alert("Il pagamento è stato avviato, ma c'è stato un problema nell'aggiornare lo stato. Contattaci se necessario.");
    } finally {
      setIsFinalizing(false);
    }
  };

  const currentStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING_PAYMENT: return 'bg-orange-100 text-orange-700';
      case OrderStatus.PAID: return 'bg-green-100 text-green-700';
      case OrderStatus.PROCESSING: return 'bg-blue-100 text-blue-700';
      case OrderStatus.PRINTED: return 'bg-purple-100 text-purple-700';
