  const handleRemovePhoto = (id: string, index: number) => {
    setUploadedPhotosPreview(prev => prev.filter(p => p.id !== id));
    setLocalFiles(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="py-12 px-4 md:px-6 bg-gray-50 min-h-screen">
