                <p className="text-gray-500 mb-6 font-bold uppercase tracking-widest text-[10px]">1. Seleziona il pacchetto</p>
                <div className="grid grid-cols-1 gap-6">
                  {PRINT_PACKAGES.map(pkg => (
                    <button 
