import { useState, useEffect } from 'react';
import { User, Order, OrderStatus, PaymentMethod } from '../types';
import { supabase } from './supabase';

const AUTH_KEY = 'studio_auth_v2';
const ADMIN_EMAIL = "carminephotography0@gmail.com";

// Interfaccia per mappare esattamente le colonne della tabella Supabase
interface SupabaseOrder {
  id: string;
  customer_email: string;
  photo_urls: string[];
  status: string;
  created_at: string;
}

export const useStore = () => {
  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem(AUTH_KEY);
    return stored ? JSON.parse(stored) : null;
  });

  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (user) {
      fetchOrders();
    }
  }, [user]);

  const fetchOrders = async () => {
    if (!user) return;
    setLoading(true);

    try {
      console.log(`[STORE] Recupero ordini per: ${user.email} (Ruolo: ${user.role})`);

      let query = supabase.from('orders').select('*');

      if (user.email !== ADMIN_EMAIL) {
        query = query.eq('customer_email', user.email);
      }

      const { data, error } = await query.order('created_at', { ascending: false });

      if (error) {
        console.error("[STORE] Errore fetch ordini Supabase:", error.message);
        return;
      }

      if (data) {
        const mappedOrders: Order[] = (data as SupabaseOrder[]).map((item) => ({
          id: item.id,
          userId: '', 
          userName: item.customer_email.split('@')[0],
          userEmail: item.customer_email,
          packageId: 'standard_100', 
          packageName: 'Pacchetto 100 Foto',
          photos: (item.photo_urls || []).map((url: string, index: number) => {
            // Estraiamo l'estensione dall'URL di Cloudinary per garantire che lo ZIP sia leggibile
            const extension = url.split('.').pop()?.split('?')[0] || 'jpg';
            return {
              id: `photo-${index}`,
              name: `Foto_${index + 1}.${extension}`,
              url: url,
              size: 0
            };
          }),
          status: (item.status as OrderStatus) || OrderStatus.PENDING_PAYMENT,
          paymentMethod: PaymentMethod.ONLINE_SUMUP,
          createdAt: item.created_at,
          total: 20 
        }));
        setOrders(mappedOrders);
        console.log(`[STORE] Caricati ${mappedOrders.length} ordini.`);
      }
    } catch (err) {
      console.error("[STORE] Eccezione nel caricamento ordini:", err);
    } finally {
      setLoading(false);
    }
  };

  const login = async (email: string, pass: string): Promise<User> => {
    const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
      email,
      password: pass,
    });

    if (authError) {
      console.error("[STORE] Errore Autenticazione Supabase:", authError.message);
      throw authError;
    }

    const role = email.toLowerCase() === ADMIN_EMAIL.toLowerCase() ? 'admin' : 'client';
    const loggedUser: User = {
      id: authData.user.id,
      name: authData.user.email?.split('@')[0] || email.split('@')[0],
      email: email.toLowerCase(),
      role: role as 'admin' | 'client',
      mustChangePassword: false
    };

    setUser(loggedUser);
    localStorage.setItem(AUTH_KEY, JSON.stringify(loggedUser));
    return loggedUser;
  };

  const signUp = async (email: string, pass: string): Promise<User> => {
    const { data: authData, error: authError } = await supabase.auth.signUp({
      email,
      password: pass,
    });

    if (authError) {
      console.error("[STORE] Errore Registrazione Supabase:", authError.message);
      throw authError;
    }

    const newUser: User = {
      id: authData.user?.id || Math.random().toString(36).substr(2, 9),
      name: email.split('@')[0],
      email: email.toLowerCase(),
      role: 'client',
      mustChangePassword: false
    };

    setUser(newUser);
    localStorage.setItem(AUTH_KEY, JSON.stringify(newUser));
    return newUser;
  };

  const logout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    localStorage.removeItem(AUTH_KEY);
    setOrders([]);
  };

  const addOrder = async (order: Order) => {
    const dbOrder = {
      customer_email: order.userEmail.toLowerCase(),
      photo_urls: order.photos.map(p => p.url),
      status: 'pending',
      created_at: new Date().toISOString()
    };

    console.log("[STORE] Invio dati a Supabase (Tabella orders):", dbOrder);

    const { data, error } = await supabase.from('orders').insert([dbOrder]).select();

    if (error) {
      console.error("[STORE] Errore salvataggio Supabase (RLS o Schema):", error);
      throw error;
    }

    console.log("[STORE] Risposta successo Supabase:", data);
    await fetchOrders();
    return data ? data[0] : null;
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus) => {
    console.log(`[STORE] Aggiornamento status ordine ${orderId} a ${status}`);
    const { error } = await supabase
      .from('orders')
      .update({ status })
      .eq('id', orderId);

    if (error) {
      console.error("[STORE] Errore update status Supabase:", error.message);
      throw error;
    }

    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status } : o));
  };

  const deleteOrder = async (orderId: string) => {
    console.log(`[STORE] Eliminazione definitiva ordine ${orderId}`);
    const { error } = await supabase
      .from('orders')
      .delete()
      .eq('id', orderId);

    if (error) {
      console.error("[STORE] Errore eliminazione Supabase:", error.message);
      throw error;
    }

    setOrders(prev => prev.filter(o => o.id !== orderId));
  };

  return {
    user,
    orders,
    loading,
    login,
    signUp,
    logout,
    addOrder,
    updateOrderStatus,
    deleteOrder,
    fetchOrders
  };
};

import * as React from 'react';
import { useState, type FC } from 'react';
import { Order, OrderStatus } from '../types';
import * as JSZip from 'jszip';
import { EmailService } from '../services/email';

interface AdminProps {
  orders: Order[];
  updateStatus: (id: string, status: OrderStatus) => void;
  deleteOrder: (id: string) => void;
  onLogout: () => void;
}

const Admin: FC<AdminProps> = ({ orders, updateStatus, deleteOrder, onLogout }) => {
  const [filter, setFilter] = useState<OrderStatus | 'all'>('all');
  const [isDownloading, setIsDownloading] = useState<string | null>(null);
  const [downloadProgress, setDownloadProgress] = useState<number>(0);

  const filteredOrders = filter === 'all' ? orders : orders.filter(o => o.status === filter);

  const handleStatusChange = async (orderId: string, newStatus: OrderStatus) => {
    updateStatus(orderId, newStatus);

    if (newStatus === OrderStatus.PRINTED) {
      const order = orders.find(o => o.id === orderId);
      if (order) {
        await EmailService.sendCollectionReady(order);
        alert(`✅ Email di ritiro inviata correttamente a ${order.userEmail}`);
      }
    }
  };

  const handleDelete = (orderId: string) => {
    const isConfirmed = window.confirm(
      "⚠ AZIONE IRREVERSIBILE\n\nSei sicuro di voler eliminare DEFINITIVAMENTE l'ordine " + orderId + "?"
    );
    if (isConfirmed) {
      deleteOrder(orderId);
      alert("✅ Ordine eliminato.");
    }
  };

  const downloadAllAsZip = async (order: Order) => {
    if (order.photos.length === 0) {
      alert("L'ordine non contiene foto.");
      return;
    }

    console.log(`[ADMIN] Inizio creazione ZIP per ordine ${order.id}`);
    setIsDownloading(order.id);
    setDownloadProgress(0);

    try {
      // Gestione sicura del costruttore JSZip per ambienti ESM
      const JSZipConstructor = (JSZip as any).default || JSZip;
      const zip = new JSZipConstructor();

      const folderName = `${order.userName.replace(/\s+/g, '_')}_${order.id.slice(0, 8)}`;
      const folder = zip.folder(folderName);

      let processedCount = 0;
      for (let i = 0; i < order.photos.length; i++) {
        const photo = order.photos[i];
        try {
          // Fondamentale: fetch con cache 'no-cache' per evitare problemi di dati corrotti e assicurare il download del blob
          const response = await fetch(photo.url, { 
            method: 'GET',
            mode: 'cors',
            cache: 'no-cache' 
          });

          if (!response.ok) throw new Error(`Errore HTTP: ${response.status}`);

          // Scarichiamo come BLOB binario
          const blob = await response.blob();

          // Verifichiamo che il nome del file abbia un'estensione valida
          const fileName = photo.name.includes('.') ? photo.name : `${photo.name}.jpg`;

          folder?.file(fileName, blob, { binary: true });
          console.log(`[ADMIN] Aggiunto allo ZIP: ${fileName}`);
        } catch (err) {
          console.error(`[ADMIN] Errore download foto ${photo.url}:`, err);
          folder?.file(`ERRORE_FOTO_${i+1}.txt`, `Impossibile scaricare questa immagine: ${photo.url}`);
        }
        processedCount++;
        setDownloadProgress(Math.round((processedCount / order.photos.length) * 100));
      }

      console.log(`[ADMIN] Generazione file ZIP in corso...`);
      const content = await zip.generateAsync({ 
        type: 'blob',
        compression: "DEFLATE",
        compressionOptions: { level: 6 }
      });

      const downloadUrl = URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `${folderName}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(downloadUrl);

      console.log(`[ADMIN] ZIP scaricato con successo.`);
    } catch (err: any) {
      console.error(`[ADMIN] Errore generazione ZIP:`, err);
      alert(`Errore critico durante la creazione dello ZIP: ${err.message}`);
    } finally {
      setIsDownloading(null);
      setDownloadProgress(0);
    }
  };

  const getStatusBadgeClass = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING_PAYMENT: return 'bg-orange-100 text-orange-700 border-orange-200';
      case OrderStatus.PAID: return 'bg-green-100 text-green-700 border-green-200';
      case OrderStatus.PROCESSING: return 'bg-blue-100 text-blue-700 border-blue-200';
      case OrderStatus.PRINTED: return 'bg-purple-100 text-purple-700 border-purple-200';
      case OrderStatus.COLLECTED: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  return (
    <div className="py-12 px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto">
        <header className="mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div>
            <h1 className="text-4xl font-serif mb-2 text-black">Area Amministratore</h1>
            <p className="text-gray-500 italic text-sm">Dashboard ordini — Carmine Felice Napolitano</p>
          </div>
          <button 
            onClick={onLogout}
            className="px-6 py-2 bg-red-600 text-white rounded-full text-[10px] font-bold uppercase tracking-widest shadow-lg hover:bg-red-700 transition-colors"
          >
            Esci Sessione
          </button>
        </header>

        <div className="flex items-center space-x-2 overflow-x-auto pb-6 scrollbar-hide mb-8">
            <button onClick={() => setFilter('all')} className={`px-5 py-2.5 rounded-full text-[10px] font-bold uppercase tracking-widest shadow-sm transition-all ${filter === 'all' ? 'bg-black text-white' : 'bg-white text-gray-400'}`}>TUTTI ({orders.length})</button>
            {Object.values(OrderStatus).map(status => (
              <button key={status} onClick={() => setFilter(status)} className={`px-5 py-2.5 rounded-full text-[10px] font-bold uppercase tracking-widest shadow-sm transition-all ${filter === status ? 'bg-black text-white' : 'bg-white text-gray-400'}`}>
                {status.toUpperCase()} ({orders.filter(o => o.status === status).length})
              </button>
            ))}
        </div>

        {filteredOrders.length === 0 ? (
          <div className="bg-white p-24 rounded-[40px] text-center shadow-sm border border-gray-100">
            <i className="fas fa-check-circle text-5xl mb-6 text-green-100"></i>
            <h3 className="text-2xl font-serif mb-3">Nessun ordine</h3>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-6">
            {filteredOrders.map(order => (
              <div key={order.id} className="bg-white p-6 md:p-8 rounded-[32px] shadow-sm border border-gray-100 flex flex-col md:flex-row md:items-center gap-8 relative overflow-hidden">
                <div className="md:w-1/4">
                  <span className="text-[9px] font-bold text-gray-300 uppercase block mb-1">Order ID: {order.id}</span>
                  <h3 className="font-bold text-xl text-black leading-tight mb-1 uppercase">{order.userName}</h3>
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{order.userEmail}</p>
                </div>

                <div className="md:w-1/4 md:border-l md:border-gray-50 md:pl-8">
                   <p className="font-bold text-black text-xs uppercase tracking-widest mb-1">{order.packageName}</p>
                   <p className="text-[10px] text-gray-400 font-bold uppercase mt-1">
                     <i className="fas fa-images mr-2"></i> {order.photos.length} FILE
                   </p>
                </div>

                <div className="md:w-2/4 flex flex-col sm:flex-row items-center justify-end gap-4">
                   <select 
                      value={order.status}
                      onChange={(e) => handleStatusChange(order.id, e.target.value as OrderStatus)}
                      className={`px-6 py-4 rounded-2xl text-[10px] font-bold uppercase tracking-widest cursor-pointer border-2 ${getStatusBadgeClass(order.status)}`}
                    >
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                   </select>

                   <button 
                      onClick={() => downloadAllAsZip(order)}
                      disabled={isDownloading === order.id}
                      className={`w-full sm:w-auto px-10 py-4 rounded-2xl transition-all flex items-center justify-center font-bold text-[10px] uppercase tracking-widest ${isDownloading === order.id ? 'bg-gray-100 text-gray-400' : 'bg-black text-white hover:bg-gray-800 shadow-xl'}`}
                    >
                      {isDownloading === order.id ? <><i className="fas fa-spinner fa-spin mr-3"></i>{downloadProgress}%</> : 'SCARICA ZIP'}
                   </button>

                   <button onClick={() => handleDelete(order.id)} className="p-4 bg-red-50 text-red-600 rounded-2xl hover:bg-red-600 hover:text-white transition-all">
                      <i className="fas fa-trash-alt"></i>
                   </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Admin;

import * as React from 'react';
import { useState, type FC } from 'react';
import { User } from '../types';

interface AuthProps {
  mode: 'login' | 'register';
  navigate: (page: string) => void;
  onLogin: (email: string, pass: string) => Promise<User>;
}

const Auth: FC<AuthProps> = ({ mode, navigate, onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (email && password) {
      setIsLoading(true);
      try {
        // Esegue il login o la registrazione tramite il servizio dedicato (Supabase)
        await onLogin(email, password);

        // Dopo un successo, reindirizza l'utente alla pagina dei pacchetti
        // come richiesto esplicitamente per migliorare il flusso di conversione.
        console.log("[AUTH] Autenticazione completata. Reindirizzamento alla galleria pacchetti.");
        navigate('packages');

      } catch (error: any) {
        // Mantiene la gestione degli errori originale per non degradare la UX
        alert("Errore Autenticazione: " + (error.message || "Email o password non corretti."));
      } finally {
        setIsLoading(false);
      }
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 px-6 py-12">
      <div className="max-w-md w-full bg-white p-10 rounded-3xl shadow-xl border border-gray-100">
        <div className="text-center mb-10">
          <h2 className="text-3xl font-serif mb-2">{mode === 'login' ? 'Accesso' : 'Crea Account'}</h2>
          <p className="text-gray-400 text-sm">
            {mode === 'login' 
              ? 'Accedi per gestire i tuoi ordini o il pannello fotografico.' 
              : 'Registrati per iniziare a stampare i tuoi ricordi.'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          {mode === 'register' && (
            <div>
              <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Nome Completo</label>
              <input 
                type="text" 
                className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-black transition-all"
                placeholder="Nome e Cognome"
              />
            </div>
          )}
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Email</label>
            <input 
              type="email" 
              required 
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-black transition-all"
              placeholder="email@esempio.it"
            />
          </div>
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Password</label>
            <input 
              type="password" 
              required 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-black transition-all"
              placeholder="••••••••"
            />
          </div>

          <button 
            type="submit"
            disabled={isLoading}
            className="w-full py-4 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-lg transition-all transform hover:scale-[1.02] disabled:opacity-50"
          >
            {isLoading ? 'Attendi...' : (mode === 'login' ? 'Entra ora' : 'Registrati')}
          </button>
        </form>

        <div className="mt-10 text-center">
          <p className="text-sm text-gray-400">
            {mode === 'login' ? "Non hai un account?" : "Hai già un account?"}
