          <div>
            <h3 className="text-[10px] font-bold uppercase tracking-widest mb-8 text-gray-500">Contatti</h3>
            <p className="text-[10px] text-gray-400 leading-relaxed uppercase tracking-widest">{STUDIO_ADDRESS}<br/>{STUDIO_PHONE}</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

