import * as React from 'react';
import { useState, useEffect, type FC, type ReactNode } from 'react';
import { APP_NAME, STUDIO_ADDRESS, STUDIO_PHONE, INSTAGRAM_URL, LOGO_URL, WHATSAPP_LINK } from '../constants';
import { User } from '../types';

interface LayoutProps {
  children: ReactNode;
  user: User | null;
  onLogout: () => void;
  navigate: (page: string) => void;
}

const Layout: FC<LayoutProps> = ({ children, user, onLogout, navigate }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDark, setIsDark] = useState(false);

  // Inizializzazione del tema all'avvio del componente
  useEffect(() => {
    const checkInitialTheme = () => {
      // Verifica se la classe 'dark' è già presente (impostata dallo script nell'head)
      // o se è salvata nel localStorage
      const isDarkMode = document.documentElement.classList.contains('dark') || 
                         localStorage.getItem('color-theme') === 'dark';

      setIsDark(isDarkMode);

      // Assicuriamoci che la classe sia sincronizzata correttamente
      if (isDarkMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    };

    checkInitialTheme();
  }, []);

  // Gestione scroll body per menu mobile
  useEffect(() => {
    if (isMobileMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
  }, [isMobileMenuOpen]);

  const toggleTheme = () => {
    if (document.documentElement.classList.contains('dark')) {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('color-theme', 'light');
      setIsDark(false);
    } else {
      document.documentElement.classList.add('dark');
      localStorage.setItem('color-theme', 'dark');
      setIsDark(true);
    }
  };

  const handleNav = (page: string) => {
    navigate(page);
    setIsMobileMenuOpen(false);
  };

