export default Auth;

import * as React from 'react';
import { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Home from './pages/Home';
import Auth from './pages/Auth';
import Dashboard from './pages/Dashboard';
import Admin from './pages/Admin';
import Contact from './pages/Contact';
import Packages from './pages/Packages';
import Portfolio from './pages/Portfolio';
import Privacy from './pages/Privacy';
import Cookie from './pages/Cookie';
import { useStore } from './services/store';
import { WHATSAPP_LINK } from './constants';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState('home');
  const store = useStore();

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      if (hash) setCurrentPage(hash);
    };
    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigate = (page: string) => {
    window.location.hash = page;
    setCurrentPage(page);
    window.scrollTo(0, 0);
  };

  const handleLogout = () => {
    store.logout();
    navigate('home');
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return <Home navigate={navigate} />;
      case 'portfolio':
        return <Portfolio navigate={navigate} />;
      case 'login':
        return <Auth mode="login" navigate={navigate} onLogin={(email, pass) => store.login(email, pass)} />;
      case 'register':
        return <Auth mode="register" navigate={navigate} onLogin={(email, pass, phone) => store.signUp(email, pass, phone || '')} />;
      case 'dashboard':
        return store.user ? (
          <Dashboard 
            user={store.user} 
            orders={store.orders}
            addOrder={store.addOrder}
            updateStatus={store.updateOrderStatus}
            navigate={navigate}
            onLogout={handleLogout}
          />
        ) : <Auth mode="login" navigate={navigate} onLogin={(email, pass) => store.login(email, pass)} />;
      case 'admin':
        return store.user?.role === 'admin' ? (
          <Admin 
            orders={store.orders} 
            updateStatus={store.updateOrderStatus} 
            deleteOrder={store.deleteOrder}
            onLogout={handleLogout}
          />
        ) : <Auth mode="login" navigate={navigate} onLogin={(email, pass) => store.login(email, pass)} />;
      case 'packages':
        return <Packages navigate={navigate} user={store.user} />;
      case 'contact':
        return <Contact />;
      case 'privacy':
        return <Privacy />;
      case 'cookie':
        return <Cookie />;
      default:
        return <Home navigate={navigate} />;
    }
  };

  return (
    <div className="relative">
      <Layout 
        user={store.user} 
        onLogout={handleLogout} 
        navigate={navigate}
